32	/** Linear merge of two PlayerFormType arrays already sorted by date then id. */
33	function mergeByDate(
34	    a: PlayerFormType[],
35	    b: PlayerFormType[],
36	): PlayerFormType[] {
37	    const result: PlayerFormType[] = [];
38	    let i = 0;
39	    let j = 0;
40	    while (i < a.length && j < b.length) {
41	        const dateDiff =
42	            a[i].gameDay!.date.getTime() - b[j].gameDay!.date.getTime();
43	        if (
44	            dateDiff < 0 ||
45	            (dateDiff === 0 && a[i].gameDay!.id <= b[j].gameDay!.id)
46	        ) {
47	            result.push(a[i++]);
48	        } else {
49	            result.push(b[j++]);
50	        }
51	    }
52	    while (i < a.length) result.push(a[i++]);
53	    while (j < b.length) result.push(b[j++]);
54	    return result;
55	}
