370	    /**
371	     * Retrieves all players on a given team for a specific game day, including
372	     * their outcome for that day and their recent form.
373	     * @param gameDayId - The game day identifier.
374	     * @param team - Team to fetch ('A' or 'B').
375	     * @param formHistory - Number of previous games to include in each
376	     * player's form graph (default 5, minimum 0).
377	     *
378	     * Form behavior:
379	     * - Uses only prior outcomes with a team assigned on a decided game day.
380	     * - Prior outcomes are returned oldest → newest.
381	     * - If fewer than formHistory outcomes exist, form is left-padded with
382	     *   unplayed sentinel entries (gameDayId: 0, points: null) so the result
383	     *   is always formHistory entries long.
384	     *
385	     * Sorting behavior:
386	     * - Players are ordered with goalies first.
387	     * - Within each group, players are ordered alphabetically by name.
388	     * @returns A promise resolving to the enriched player records.
389	     * @throws If there is an error fetching the data.
390	     */
391	    async getTeamPlayersByGameDay(
392	        gameDayId: number,
393	        team: TeamName,
394	        formHistory = 5,
395	    ): Promise<TeamPlayerType[]> {
396	        const validatedGameDayId = z.number().int().min(1).parse(gameDayId);
397	        const validatedTeam = TeamNameSchema.parse(team);
398	        const validatedHistory = z.number().int().min(0).parse(formHistory);
399	
400	        const outcomes = await prisma.outcome.findMany({
401	            where: {
402	                gameDayId: validatedGameDayId,
403	                team: validatedTeam,
404	            },
405	            include: {
406	                gameDay: true,
407	                player: {
408	                    include: {
409	                        outcomes: {
410	                            where: {
411	                                gameDayId: { lt: validatedGameDayId },
412	                                team: { not: null },
413	                                gameDay: {
414	                                    status: { in: ['AWin', 'BWin', 'Draw'] },
415	                                },
416	                            },
417	                            orderBy: { gameDayId: 'desc' },
418	                            take: validatedHistory,
419	                            include: { gameDay: true },
420	                        },
421	                    },
422	                },
423	            },
424	            orderBy: [{ goalie: 'desc' }, { player: { name: 'asc' } }],
425	        });
426	
427	        return outcomes.map(({ player, gameDay, ...outcome }) => {
428	            if (!player) {
429	                throw new InternalError(
430	                    `Outcome ${outcome.id} is missing its player relation.`,
431	                    {
432	                        details: {
433	                            outcomeId: outcome.id,
434	                            gameDayId: outcome.gameDayId,
435	                            playerId: outcome.playerId,
436	                            team: outcome.team,
437	                        },
438	                    },
439	                );
440	            }
441	            const { outcomes: playerOutcomes = [], ...playerData } = player;
442	
443	            // Outcomes arrive newest-first; reverse so the arc reads oldest→newest.
444	            const actualForm = [...playerOutcomes]
445	                .reverse()
446	                .map(({ gameDay: formGameDay, ...formOutcome }) => ({
447	                    ...formOutcome,
448	                    gameDay: formGameDay,
449	                    points: getPlayerPoints(
450	                        formGameDay.status,
451	                        formOutcome.team,
452	                    ),
453	                }));
454	
455	            // Left-pad with unplayed sentinels for players newer than formHistory games.
456	            const paddingCount = Math.max(
457	                0,
458	                validatedHistory - actualForm.length,
459	            );
460	            const padding = Array.from({ length: paddingCount }, () => ({
461	                id: 0,
462	                gameDayId: 0,
463	                playerId: playerData.id,
464	                response: null,
465	                responseInterval: null,
466	                points: null,
467	                team: null,
468	                comment: null,
469	                pub: null,
470	                goalie: null,
471	            }));
472	
473	            return TeamPlayerSchema.parse({
474	                ...playerData,
475	                outcome: {
476	                    ...outcome,
477	                    points: getPlayerPoints(gameDay.status, outcome.team),
478	                },
479	                form: [...padding, ...actualForm],
480	            });
481	        });
482	    }
