508	    /**
509	     * Retrieves all outcomes for a player across a given year, or all time when
510	     * year is 0. Also includes game days where the player had no outcome
511	     * (not invited) and scheduled days where no game took place
512	     * (status = NoGame) as synthetic entries with null points, so the result
513	     * is suitable for building a full activity heatmap with no gaps.
514	     *
515	     * @param playerId - The ID of the player.
516	     * @param year - The year to filter by, or 0 for all time.
517	     * @param fromDate - Optional earliest date (inclusive). Game days before
518	     * this date are excluded. Useful for filtering to a player's joined date.
519	     * @param toDate - Optional latest date (inclusive). Game days after this
520	     * date are excluded. Useful for filtering to a player's finished date.
521	     * @returns A promise that resolves to outcomes with game days, ordered by
522	     * game day date ascending, with game day ID as a tiebreaker. No-game days
523	     * and uninvited game days are represented as synthetic entries with
524	     * points = null; no-game days have gameDay.status = NoGame.
525	     */
526	    async getHistoryByPlayer(
527	        playerId: number,
528	        year: number,
529	        fromDate?: Date,
530	        toDate?: Date,
531	    ): Promise<PlayerFormType[]> {
532	        const {
533	            playerId: pid,
534	            year: yr,
535	            fromDate: from,
536	            toDate: to,
537	        } = z
538	            .object({
539	                playerId: z.number().int().min(1),
540	                year: z.union([
541	                    z.literal(0),
542	                    z.number().int().min(1900).max(2100),
543	                ]),
544	                fromDate: z.date().optional(),
545	                toDate: z.date().optional(),
546	            })
547	            .parse({ playerId, year, fromDate, toDate });
548	
549	        // All day-boundary arithmetic uses UTC midnight so results are stable
550	        // across timezones and DST transitions.
551	        const utcDay = (y: number, m: number, d: number) =>
552	            new Date(Date.UTC(y, m, d));
553	        const utcDayOf = (date: Date) =>
554	            utcDay(
555	                date.getUTCFullYear(),
556	                date.getUTCMonth(),
557	                date.getUTCDate(),
558	            );
559	        const utcNextDayOf = (date: Date) =>
560	            utcDay(
561	                date.getUTCFullYear(),
562	                date.getUTCMonth(),
563	                date.getUTCDate() + 1,
564	            );
565	
566	        const yearStart = yr > 0 ? utcDay(yr, 0, 1) : undefined;
567	        // When both bounds are present, take the later start so neither is silently ignored.
568	        const startDate =
569	            yearStart && from
570	                ? new Date(
571	                      Math.max(yearStart.getTime(), utcDayOf(from).getTime()),
572	                  )
573	                : (yearStart ?? (from ? utcDayOf(from) : undefined));
574	        const yearEnd = yr > 0 ? utcDay(yr + 1, 0, 1) : undefined;
575	        // For toDate, convert the inclusive finished date to an exclusive upper bound (next UTC day),
576	        // then take the earliest of the year end, player finish, and tomorrow (no future game days).
577	        const finishedEnd = to ? utcNextDayOf(to) : undefined;
578	        const tomorrow = utcNextDayOf(new Date());
579	        const candidates = [yearEnd, finishedEnd, tomorrow].filter(
580	            (d): d is Date => d !== undefined,
581	        );
582	        const endDate = new Date(
583	            Math.min(...candidates.map((d) => d.getTime())),
584	        );
585	        // endDate is always defined: candidates always contains tomorrow.
586	        const dateRange: { gte?: Date; lt: Date } = { lt: endDate };
587	        if (startDate) dateRange.gte = startDate;
588	        const dateFilter = { date: dateRange };
589	
590	        const [rawOutcomes, dateRangeGameDays] = await Promise.all([
591	            prisma.outcome.findMany({
592	                where: {
593	                    playerId: pid,
594	                    gameDay: { status: { not: 'NoGame' }, ...dateFilter },
595	                },
596	                orderBy: [{ gameDay: { date: 'asc' } }, { gameDayId: 'asc' }],
597	                include: { gameDay: true },
598	            }),
599	            gameDayService.getAll({
600	                fromDate: startDate,
601	                beforeDate: endDate,
602	            }),
603	        ]);
604	
605	        const outcomes: PlayerFormType[] = rawOutcomes.map((o) => ({
606	            ...o,
607	            points: getPlayerPoints(o.gameDay.status, o.team),
608	        }));
609	        const noGameDays = dateRangeGameDays.filter((gd) => !isGame(gd.status));
610	        const allGameDays = dateRangeGameDays.filter((gd) => isGame(gd.status));
611	
612	        const playedIds = new Set(outcomes.map((o) => o.gameDayId));
613	        const makeSynthetic = (
614	            gameDay: (typeof noGameDays)[number],
615	        ): PlayerFormType => ({
616	            id: -gameDay.id,
617	            gameDayId: gameDay.id,
618	            playerId: pid,
619	            response: null,
620	            responseInterval: null,
