807	/**
808	 * Calculates the player record for a specific year and game day based on the
809	 * provided outcomes.
810	 * @param year - The year of the player record.
811	 * @param gameDay - The game day for which the player record is calculated.
812	 * @param yearOutcomes - The outcomes for the entire year.
813	 * @param outcome - The outcome for the specific game day.
814	 * @param statusById - A lookup from game day ID to its status, covering
815	 * every game day referenced by `yearOutcomes`, used to derive each outcome's
816	 * points.
817	 * @returns A promise that resolves to a partial player record object.
818	 */
819	function calculatePlayerRecord(
820	    year: number,
821	    gameDay: GameDayType,
822	    yearOutcomes: OutcomeType[],
823	    outcome: OutcomeType,
824	    statusById: Map<number, GameDayStatus>,
825	): Partial<PlayerRecordType> {
826	    const pointsOf = (o: OutcomeType) => {
827	        const status = statusById.get(o.gameDayId);
828	        if (status === undefined) {
829	            throw new InternalError(
830	                `GameDay ${o.gameDayId} is missing from the status map while computing points for player ${o.playerId}.`,
831	                { details: { gameDayId: o.gameDayId, playerId: o.playerId } },
832	            );
833	        }
834	        return getPlayerPoints(status, o.team ?? null);
835	    };
836	
837	    const playerYearOutcomes = yearOutcomes
838	        .filter(
839	            (o) => o.playerId === outcome.playerId && o.gameDayId <= gameDay.id,
840	        )
841	        .map((o) => ({ outcome: o, points: pointsOf(o) }));
842	    const playerYearRespondedOutcomes = playerYearOutcomes.filter(
843	        ({ outcome: o }) => o.response != null,
844	    );
845	    const playerYearPlayedOutcomes = playerYearOutcomes.filter(
846	        ({ points }) => points != null,
847	    );
848	    const pub = playerYearOutcomes.reduce(
849	        (acc, { outcome: o }) => acc + (o.pub ?? 0),
850	        0,
851	    );
852	    const data: Partial<PlayerRecordType> = {
853	        playerId: outcome.playerId,
854	        year: year,
855	        gameDayId: gameDay.id,
856	        responses: playerYearRespondedOutcomes.length,
857	        points: pointsOf(outcome),
858	        ...{ scorePub: pub > 0 ? pub : null },
859	    };
860	
861	    if (playerYearPlayedOutcomes.length > 0) {
862	        data.played = playerYearPlayedOutcomes.length;
863	        data.won = playerYearPlayedOutcomes.filter(
864	            ({ points }) => points == 3,
865	        ).length;
866	        data.drawn = playerYearPlayedOutcomes.filter(
867	            ({ points }) => points == 1,
868	        ).length;
869	        data.lost = playerYearPlayedOutcomes.filter(
870	            ({ points }) => points == 0,
871	        ).length;
872	    }
873	
874	    if (data.played && data.played > 0) {
875	        const totalPoints = playerYearPlayedOutcomes.reduce(
876	            (acc, { points }) => acc + points!,
877	            0,
878	        );
879	        data.scorePoints = totalPoints;
880	        data.scoreAverages = totalPoints / data.played;
881	    }
882	
883	    const responseIntervals = playerYearOutcomes
884	        .map(({ outcome: o }) => o.responseInterval)
885	        .filter((num): num is number => num != null);
886	
887	    if (responseIntervals.length > 0) {
888	        data.scoreSpeedy =
889	            responseIntervals.reduce((acc, ri) => acc + ri, 0) /
890	            responseIntervals.length;
891	    }
892	
893	    return data;
894	}
