async getByPlayer(
    playerId: number,
): Promise<(OutcomeType & { points: PointsValue | null })[]> {
    const [outcomes, playerRecords] = await Promise.all([
        prisma.outcome.findMany({
            where: {
                playerId: playerId,
            },
        }),
        prisma.playerRecord.findMany({
            where: { playerId, year: 0 },
            select: { gameDayId: true, points: true },
        }),
    ]);
    const pointsByGameDay = new Map(
        playerRecords.map((r) => [
            r.gameDayId,
            r.points as PointsValue | null,
        ]),
    );

    return outcomes.map((outcome) => ({
        ...outcome,
        points: pointsByGameDay.get(outcome.gameDayId) ?? null,
    }));
}

