const { execSync } = require('child_process');

const current = yaml.load(fs.readFileSync('docs/ontology.yaml', 'utf8'));
const original = yaml.load(execSync('git show HEAD:docs/ontology.yaml').toString());

function normalize(v) {
  if (typeof v === 'string') return v.replace(/\s+/g, ' ').trim();
  if (Array.isArray(v)) return v.map(normalize);
  if (v && typeof v === 'object') {
    const out = {};
    for (const k of Object.keys(v)) out[k] = normalize(v[k]);
    return out;
  }
  return v;
}

const a = JSON.stringify(normalize(current));
const b = JSON.stringify(normalize(original));
console.log('Semantically identical (whitespace-normalized):', a === b);
if (a !== b) {
  fs.writeFileSync('/tmp/a.json', a);
  fs.writeFileSync('/tmp/b.json', b);
}
